// ❌ DB 구조, 스택 트레이스 노출
try {
  await db.query(...)
} catch (error) {
  res.status(500).json({ error: error.message })
  // → "Table 'mydb.users' doesn't exist" 같은 정보 노출
  // → 공격자가 DB 구조 파악 가능
}

// ✅ 일반적인 메시지만 반환
try {
  await db.query(...)
} catch (error) {
  console.error(error)  // 서버 로그에만 기록
  res.status(500).json({ error: '서버 오류가 발생했습니다' })
}

